  { key: "actions", label: "Actions", width: 110 },
];

const ROW_HEIGHT = 44;
const HEADER_HEIGHT = 44;
const TABLE_WIDTH = COLUMNS.reduce((sum, col) => sum + col.width, 0);

const VirtualRow = memo(function VirtualRow({ index, style, data }) {
  const record = data[index];

  return (
    <div
      role="row"
      aria-rowindex={index + 2}
      className="virtual-row"
      style={{ ...style, width: TABLE_WIDTH }}
    >
      {COLUMNS.map((column) => (
        <div
          key={column.key}
          role="cell"
          className="virtual-cell"
          style={{ width: column.width }}
          title={String(record[column.key] ?? "")}
        >
          {column.key === "actions" ? (
            <button
              type="button"
              onClick={() => data.onEdit?.(record)}
              aria-label={`Edit record ${record.id}`}
            >
              Edit
            </button>
          ) : (
            String(record[column.key] ?? "—")
          )}
        </div>
      ))}
    </div>
  );
});

export default function VirtualizedTable({ rows, onEdit }) {
  const itemData = useMemo(
    () => Object.assign([...rows], { onEdit }),
    [rows, onEdit]
  );

  return (
    <section className="table-container" aria-label="Admin records">
      <div
        role="table"
        aria-label="Administrative records"
        aria-rowcount={rows.length + 1}
        aria-colcount={COLUMNS.length}
        className="virtual-table"
      >
        <div
          role="row"
          aria-rowindex={1}
          className="virtual-header"
          style={{ width: TABLE_WIDTH, height: HEADER_HEIGHT }}
        >
          {COLUMNS.map((column) => (
            <div
              key={column.key}
              role="columnheader"
              className="virtual-cell header-cell"
              style={{ width: column.width }}
            >
              {column.label}
            </div>
          ))}
        </div>

        <FixedSizeList
          height={500}
          width="100%"
          itemCount={rows.length}
          itemSize={ROW_HEIGHT}
          itemData={itemData}
          overscanCount={5}
          itemKey={(index, data) => data[index].id}
        >
          {VirtualRow}
        </FixedSizeList>
      </div>
    </section>
  );
}

full_response:
# Solution: Virtualize the Data Table in React

As a Senior Software Architect, I recommend row virtualization for this admin dashboard. Rendering 5,000 rows × 15 columns creates 75,000 table cells, which can impose significant DOM, layout, and paint costs.

Virtualization renders only the rows visible in the viewport, plus a small overscan buffer. For example, if the viewport displays 25 rows, the browser might render only 35–45 rows instead of all 5,000.

## 1. Recommended approach

Option A: Row virtualization — recommended

Best when administrators need to scroll through thousands of records in one continuous table. Keeps DOM size small while preserving the scrolling experience.

Option B: Server-side pagination

Best when the database contains millions of records, requests are expensive, or users need explicit page navigation. Fetch only 25–100 records per request.

## 2. React implementation using virtualization

Install the lightweight `react-window` library and use its `FixedSizeList` component to render only the visible rows. This example uses the API from `react-window` v1.x.

```
import React, { memo, useMemo } from "react";
import { FixedSizeList } from "react-window";

const COLUMNS = [
  { key: "id", label: "ID", width: 90 },
  { key: "name", label: "Name", width: 180 },
  { key: "email", label: "Email", width: 260 },
  { key: "department", label: "Department", width: 160 },
  { key: "status", label: "Status", width: 120 },
  { key: "createdAt", label: "Created", width: 150 },
  { key: "role", label: "Role", width: 130 },
  { key: "location", label: "Location", width: 150 },
  { key: "lastLogin", label: "Last Login", width: 170 },
  { key: "team", label: "Team", width: 130 },
  { key: "manager", label: "Manager", width: 150 },
  { key: "plan", label: "Plan", width: 110 },
  { key: "usage", label: "Usage", width: 100 },
  { key: "updatedAt", label: "Updated", width: 150 },
  { key: "actions", label: "Actions", width: 110 },
];

const ROW_HEIGHT = 44;
const HEADER_HEIGHT = 44;
const TABLE_WIDTH = COLUMNS.reduce((sum, col) => sum + col.width, 0);

const VirtualRow = memo(function VirtualRow({ index, style, data }) {
  const record = data[index];

  return (
    <div
      role="row"
      aria-rowindex={index + 2}
      className="virtual-row"
      style={{ ...style, width: TABLE_WIDTH }}
    >
      {COLUMNS.map((column) => (
        <div
          key={column.key}
          role="cell"
          className="virtual-cell"
          style={{ width: column.width }}
          title={String(record[column.key] ?? "")}
        >
          {column.key === "actions" ? (
            <button
              type="button"
              onClick={() => data.onEdit?.(record)}
              aria-label={`Edit record ${record.id}`}
            >
              Edit
            </button>
          ) : (
            String(record[column.key] ?? "—")
          )}
        </div>
      ))}
    </div>
  );
});

export default function VirtualizedTable({ rows, onEdit }) {
  const itemData = useMemo(
    () => Object.assign([...rows], { onEdit }),
    [rows, onEdit]
  );

  return (
    <section className="table-container" aria-label="Admin records">
      <div
        role="table"
        aria-label="Administrative records"
        aria-rowcount={rows.length + 1}
        aria-colcount={COLUMNS.length}
        className="virtual-table"
      >
        <div
          role="row"
          aria-rowindex={1}
          className="virtual-header"
          style={{ width: TABLE_WIDTH, height: HEADER_HEIGHT }}
        >
          {COLUMNS.map((column) => (
            <div
              key={column.key}
              role="columnheader"
              className="virtual-cell header-cell"
              style={{ width: column.width }}
            >
              {column.label}
            </div>
          ))}
        </div>

        <FixedSizeList
          height={500}
          width="100%"
          itemCount={rows.length}
          itemSize={ROW_HEIGHT}
          itemData={itemData}
          overscanCount={5}
          itemKey={(index, data) => data[index].id}
        >
          {VirtualRow}
        </FixedSizeList>
      </div>
    </section>
  );
}
```

Use this CSS alongside the component:

```
.table-container {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}

.virtual-table {
  min-width: 100%;
  font: 14px/1.4 system-ui, sans-serif;
}

.virtual-header,
.virtual-row {
  display: flex;
}

.virtual-header {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #f8fafc;
  border-bottom: 1px solid #cbd5e1;
}

.virtual-row {
  border-bottom: 1px solid #e5e7eb;
}

.virtual-cell {
  box-sizing: border-box;
  flex: 0 0 auto;
  padding: 10px 12px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.header-cell {
  font-weight: 600;
}

.virtual-row:hover {
  background: #f1f5f9;
}
```

The example includes 15 representative columns; map their keys to your actual data schema. The CSS and JavaScript are separate files in a typical project, but the implementation can be consolidated if required.

### How the solution works

- Virtualization: `FixedSizeList` mounts only visible rows and a small overscan buffer.
- Stable row identity: `itemKey` uses the record ID to reduce unnecessary remounting.
- Memoized rows: `React.memo` helps avoid redundant row rendering when props remain unchanged.
- Horizontal scrolling: The fixed column widths preserve the table structure on narrower screens.
- Bounded rendering: The fixed-height list avoids creating thousands of row elements simultaneously.

Important: `react-window` v1.x is used here. Check the installed version before copying the code because newer major versions have different APIs. The sample also assumes every row has a unique `id`, fixed row height, and data already available in memory.

## 3. When pagination is the better choice

If retrieving the 5,000 records itself takes several seconds, virtualization will not fix the network or database bottleneck. Use server-side pagination in that case:

- Fetch 50–100 records per page.
- Apply filtering and sorting in the database.
- Return the total count separately or use an efficient count strategy.
- Add indexes for commonly filtered and sorted fields.
- Cancel stale requests when users change filters quickly.

For many enterprise admin dashboards, the strongest architecture is server-side pagination for data retrieval combined with virtualization when each result set is still large.

## 4. Expected impact and validation

| Metric                | Current             | Initial target           |
| --------------------- | ------------------- | ------------------------ |
| Rendered rows         | 5,000               | Approximately 25–45      |
| DOM table cells       | 75,000              | Approximately 375–675    |
| Initial UI freeze     | 4–5 seconds         | Aim for under 200–300 ms |
| Scroll responsiveness | Freezes during load | Smooth scrolling         |

These are engineering targets, not guaranteed measurements. Actual performance depends on cell complexity, data processing, browser, device, and the cost of fetching the data.

My recommendation: implement virtualization first if the records are already loaded and rendering is the bottleneck. Profile the result using Chrome DevTools Performance and React Profiler, then add server-side pagination if data transfer or backend processing is also expensive.

code:
import React, { useEffect, useReducer, useRef } from "react";

const initialState = {
  step: "address",
  address: { name: "", email: "", line1: "", city: "", postalCode: "" },
  errors: {},
  checkoutId: null,
  message: "",
};

function reducer(state, action) {
  switch (action.type) {
    case "FIELD_CHANGE":
      return {
        ...state,
        address: { ...state.address, [action.name]: action.value },
        errors: { ...state.errors, [action.name]: "" },
        message: "",
      };

    case "VALIDATING":
      return { ...state, step: "validating", errors: {}, message: "" };

    case "ADDRESS_INVALID":
      return {
        ...state,
        step: "address",
        errors: action.errors,
        message: "Please correct the highlighted fields.",
      };

    case "CREATING_CHECKOUT":
      return { ...state, step: "creating_checkout", message: "" };

    case "REDIRECTING":
      return {
        ...state,
        step: "redirecting",
        checkoutId: action.checkoutId,
        message: "Redirecting securely to the payment provider…",
      };

    case "VERIFYING":
      return {
        ...state,
        step: "verifying",
        checkoutId: action.checkoutId,
        message: "Verifying your payment. Please keep this page open.",
      };

    case "PAYMENT_CONFIRMED":
      return { ...state, step: "confirmed", message: "" };

    case "PAYMENT_FAILED":
      return {
        ...state,
        step: "payment_failed",
        message: action.message,
      };

    case "RECOVER":
      return {
        ...state,
        step: "address",
        message: action.message || "",
      };

    default:
      return state;
  }
}

export default function Checkout() {
  const [state, dispatch] = useReducer(reducer, initialState);
  const inFlight = useRef(false);
  const started = useRef(false);

  // If the gateway returns the customer to this page, verify payment
  // through our backend instead of trusting URL parameters.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const checkoutId = params.get("checkout_id");

    if (!checkoutId || started.current) return;
    started.current = true;

    let cancelled = false;
    let timer;
    let attempts = 0;
    const maxAttempts = 20;

    async function verifyPayment() {
      if (cancelled) return;

      dispatch({ type: "VERIFYING", checkoutId });

      try {
        const response = await fetch(
          `/api/checkout/${encodeURIComponent(checkoutId)}/status`,
          { credentials: "same-origin" }
        );

        if (!response.ok) throw new Error("Status unavailable");

        const result = await response.json();
        if (cancelled) return;

        if (result.status === "paid") {
          dispatch({ type: "PAYMENT_CONFIRMED" });
          return;
        }

        if (result.status === "failed" || result.status === "cancelled") {
          dispatch({
            type: "PAYMENT_FAILED",
            message: "Payment was not completed. You can retry securely.",
          });
          return;
        }

        if (attempts++ < maxAttempts) {
          timer = setTimeout(verifyPayment, 2000);
        } else {
          dispatch({
            type: "PAYMENT_FAILED",
            message:
              "Payment confirmation is taking longer than expected. " +
              "Check your order status before attempting another payment.",
          });
        }
      } catch {
        if (!cancelled) {
          dispatch({
            type: "PAYMENT_FAILED",
            message:
              "We could not retrieve your payment status. " +
              "Your payment may still be processing. Check your order status before retrying.",
          });
        }
      }
    }

    void verifyPayment();

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, []);

  function updateField(event) {
    dispatch({
      type: "FIELD_CHANGE",
      name: event.target.name,
      value: event.target.value,
    });
  }

  async function submitCheckout(event) {
    event.preventDefault();

    if (inFlight.current) return;
    inFlight.current = true;

    // Reuse this key for retries of the same logical checkout attempt.
    // A production implementation should persist the attempt ID safely
    // and let the server enforce idempotency.
    const idempotencyKey = crypto.randomUUID();

    try {
      dispatch({ type: "VALIDATING" });

      const validationResponse = await fetch("/api/checkout/validate-address", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify(state.address),
      });

      const validation = await validationResponse.json();

      if (!validationResponse.ok || !validation.valid) {
        dispatch({
          type: "ADDRESS_INVALID",
          errors: validation.errors || {},
        });
        return;
      }

      dispatch({ type: "CREATING_CHECKOUT" });

      const checkoutResponse = await fetch("/api/checkout/session", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": idempotencyKey,
        },
        credentials: "same-origin",
        body: JSON.stringify({
          address: state.address,
          addressToken: validation.addressToken,
        }),
      });

      const checkout = await checkoutResponse.json();

      if (!checkoutResponse.ok) {
        throw new Error(
          checkout.message || "Unable to create checkout session."
        );
      }

      if (!checkout.checkoutId || !checkout.redirectUrl) {
        throw new Error("The checkout session response is incomplete.");
      }

      // In production, validate redirect destinations against an
      // explicit payment-provider allowlist.
      const redirect = new URL(checkout.redirectUrl);
      const allowedHosts = ["payments.example.com"];

      if (
        redirect.protocol !== "https:" ||
        !allowedHosts.includes(redirect.hostname)
      ) {
        throw new Error("The payment destination could not be verified.");
      }

      dispatch({
        type: "REDIRECTING",
        checkoutId: checkout.checkoutId,
      });

      // Release the client lock only if navigation fails or the user
      // returns. The backend must still enforce idempotency.
      window.location.assign(redirect.href);
    } catch (error) {
      dispatch({
        type: "RECOVER",
        message:
          error.message ||
          "Something went wrong. Your address has been preserved; please retry.",
      });
    } finally {
      inFlight.current = false;
    }
  }

  if (state.step === "confirmed") {
    return (
      <main className="checkout-panel" aria-live="polite">
        <h1>Payment confirmed</h1>
        <p>Your payment has been verified successfully.</p>
        <a href="/account/orders">View your orders</a>
      </main>
    );
  }

  if (state.step === "verifying") {
    return (
      <main className="checkout-panel" aria-live="polite">
        <h1>Confirming your payment</h1>
        <p role="status">{state.message}</p>
        <p>Please do not submit another payment while we check its status.</p>
      </main>
    );
  }

  if (state.step === "payment_failed") {
    return (
      <main className="checkout-panel" aria-live="polite">
        <h1>Payment status needs attention</h1>
        <p role="alert">{state.message}</p>
        <a href="/account/orders">Check your order status</a>
        <p>Contact support if the status remains unclear.</p>
      </main>
    );
  }

  const busy = [
    "validating",
    "creating_checkout",
    "redirecting",
  ].includes(state.step);

  return (
    <main className="checkout-panel">
      <h1>Complete your order</h1>

      <ol className="checkout-progress" aria-label="Checkout progress">
        <li>Cart</li>
        <li aria-current="step">Delivery details</li>
        <li>Payment</li>
      </ol>

      <form onSubmit={submitCheckout}>
        {[
          ["name", "Full name", "text"],
          ["email", "Email address", "email"],
          ["line1", "Street address", "text"],
          ["city", "City", "text"],
          ["postalCode", "Postal code", "text"],
        ].map(([name, label, type]) => (
          <div className="form-field" key={name}>
            <label htmlFor={name}>{label}</label>
            <input
              id={name}
              name={name}
              type={type}
              autoComplete={
                {
                  name: "name",
                  email: "email",
                  line1: "address-line1",
                  city: "address-level2",
                  postalCode: "postal-code",
                }[name]
              }
              value={state.address[name]}
              onChange={updateField}
              aria-invalid={Boolean(state.errors[name])}
              aria-describedby={
                state.errors[name] ? `${name}-error` : undefined
              }
              required
              disabled={busy}
            />
            {state.errors[name] && (
              <p id={`${name}-error`} className="field-error">
                {state.errors[name]}
              </p>
            )}
          </div>
        ))}

        {state.message && (
          <p
            className="checkout-message"
            role={busy ? "status" : "alert"}
            aria-live="polite"
          >
            {state.message}
          </p>
        )}

        <button
          className="checkout-button"
          type="submit"
          disabled={busy}
        >
          {state.step === "validating"
            ? "Validating address…"
            : state.step === "creating_checkout"
              ? "Preparing secure payment…"
              : state.step === "redirecting"
                ? "Redirecting securely…"
                : "Continue to payment"}
        </button>

        <p className="secure-note">
          Your payment will be processed securely by our payment provider.
        </p>
      </form>
    </main>
  );
}

