import React, {
  Suspense,
  lazy,
  useEffect,
  useState,
} from "react";

const MetricsWidget = lazy(() => import("./widgets/MetricsWidget"));
const ActivityWidget = lazy(() => import("./widgets/ActivityWidget"));
const SetupWidget = lazy(() => import("./widgets/SetupWidget"));

function WidgetSkeleton() {
  return (
    <div className="widget-skeleton" role="status" aria-live="polite">
      Loading content…
    </div>
  );
}

export function QuickSignup() {
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  async function handleSignup(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) return;

    setSubmitting(true);
    setError("");

    const form = new FormData(event.currentTarget);

    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({
          name: form.get("name"),
          email: form.get("email"),
          password: form.get("password"),
        }),
      });

      if (!response.ok) {
        throw new Error(
          response.status === 409
            ? "An account with this email already exists."
            : "We couldn't create your account. Please try again."
        );
      }

      // The backend should establish a secure session and create
      // a starter workspace before returning success.
      window.location.assign("/app");
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Something went wrong."
      );
      setSubmitting(false);
    }
  }

  return (
    <main className="onboarding">
      <section className="signup-card">
        <h1>Get started with your workspace</h1>
        <p>Create your account and explore the product in minutes.</p>

        <form onSubmit={handleSignup}>
          <label htmlFor="name">Your name</label>
          <input
            id="name"
            name="name"
            autoComplete="name"
            required
            maxLength={100}
          />

          <label htmlFor="email">Work email</label>
          <input
            id="email"
            name="email"
            type="email"
            autoComplete="email"
            required
          />

          <label htmlFor="password">Password</label>
          <input
            id="password"
            name="password"
            type="password"
            autoComplete="new-password"
            minLength={12}
            required
          />

          {error && <p role="alert">{error}</p>}

          <button type="submit" disabled={submitting}>
            {submitting ? "Creating your workspace…" : "Create free account"}
          </button>
        </form>

        <p className="secondary-note">
          You can complete your profile and configure your workspace later.
        </p>
      </section>
    </main>
  );
}

