      <details>
        <summary>Optional: personalize your workspace</summary>
        <p>Add your role, team size, and preferences when you're ready.</p>
        <a href="/app/settings/profile">Complete your profile</a>
      </details>

      <button onClick={() => setCompleted(true)} disabled={completed}>
        {completed ? "Step acknowledged" : "I'll do this later"}
      </button>
    </article>
  );
}

