import React, { lazy, Suspense, useTransition, useState, memo } from 'react';

// Heavy below-the-fold sections are code-split
const ProductGrid = lazy(() => import('./ProductGrid'));
const Recommendations = lazy(() => import('./Recommendations'));

// Lightweight skeleton that matches final layout dimensions (prevents CLS)
const MobileSkeleton = memo(() => (
  <div className="mobile-shell">
    <header className="header-skeleton" style={{ height: '56px' }} />
    <div className="hero-skeleton" style={{ aspectRatio: '16/9', width: '100%' }} />
    <div className="card-list">
      {Array.from({ length: 4 }).map((_, i) => (
        <div key={i} className="card-skeleton" style={{ height: '180px', marginBottom: '12px' }} />
      ))}
    </div>
  </div>
));

export const MobileOptimizedApp = () => {
  const [isPending, startTransition] = useTransition();
  const [showHeavyContent, setShowHeavyContent] = useState(false);

  // Defer non-critical work so the main thread stays free for TTI
  const loadHeavyContent = () => {
    startTransition(() => {
      setShowHeavyContent(true);
    });
  };

  return (
    <div className="app mobile-first">
      {/* Critical above-the-fold content ships immediately */}
      <header className="sticky-header">
        <h1>Store</h1>
        <button onClick={loadHeavyContent} disabled={isPending}>
          {isPending ? 'Loading…' : 'Browse products'}
        </button>
      </header>

      <Suspense fallback={<MobileSkeleton />}>
        {showHeavyContent ? (
          <>
            <ProductGrid />
            <Recommendations />
          </>
        ) : (
          <MobileSkeleton />
        )}
      </Suspense>
    </div>
  );
};

full_response:
**Recommended Approach**

On slow 3G/4G networks the biggest TTI killers are large JavaScript bundles, layout thrashing, and late-rendered content that causes reflows. The single most effective React pattern is to:

- Split the critical path aggressively with `React.lazy` + `Suspense`
- Render a stable mobile-first skeleton immediately
- Defer non-critical UI with concurrent features (`useTransition`)
- Eliminate layout shifts with reserved space and fluid units

Below is a production-ready React component that applies these principles.

```tsx
