import React, { useMemo } from 'react';
import { FixedSizeList as List } from 'react-window';

const ROW_HEIGHT = 48;
const VISIBLE_HEIGHT = 600; // adjust to your container

interface RowData {
  id: number;
  [key: string]: string | number;
}

const columns = Array.from({ length: 15 }, (_, i) => `col_${i + 1}`);

// Memoized row renderer – only re-renders when its data changes
const VirtualRow = React.memo(({ index, style, data }: {
  index: number;
  style: React.CSSProperties;
  data: RowData[];
}) => {
  const row = data[index];
  return (
    <div style={style} className="table-row">
      {columns.map((col) => (
        <div key={col} className="table-cell">
          {row[col]}
        </div>
      ))}
    </div>
  );
});

export const VirtualizedTable = ({ rows }: { rows: RowData[] }) => {
  // Keep a stable reference so the list doesn’t re-render unnecessarily
  const itemData = useMemo(() => rows, [rows]);

  return (
    <div className="table-container">
      {/* Sticky header */}
      <div className="table-header">
        {columns.map((col) => (
          <div key={col} className="table-cell header-cell">
            {col}
          </div>
        ))}
      </div>

      <List
        height={VISIBLE_HEIGHT}
        itemCount={rows.length}
        itemSize={ROW_HEIGHT}
        width="100%"
        itemData={itemData}
        overscanCount={8}
      >
        {VirtualRow}
      </List>
    </div>
  );
};

full_response:
**Recommended Solution**

For a 5,000+ row × 15 column table, client-side rendering of the full DOM is the root cause of the freeze. The correct fix is **row virtualization** (render only the visible rows + a small overscan buffer). Pagination is a simpler alternative but feels worse for power users; virtualization keeps the full dataset accessible while eliminating the 4–5 second lock-up.

```tsx
import React, { useMemo } from 'react';
import { FixedSizeList as List } from 'react-window';

const ROW_HEIGHT = 48;
const VISIBLE_HEIGHT = 600; // adjust to your container

interface RowData {
  id: number;
  [key: string]: string | number;
}

const columns = Array.from({ length: 15 }, (_, i) => `col_${i + 1}`);

// Memoized row renderer – only re-renders when its data changes
const VirtualRow = React.memo(({ index, style, data }: {
  index: number;
  style: React.CSSProperties;
  data: RowData[];
}) => {
  const row = data[index];
  return (
    <div style={style} className="table-row">
      {columns.map((col) => (
        <div key={col} className="table-cell">
          {row[col]}
        </div>
      ))}
    </div>
  );
});

export const VirtualizedTable = ({ rows }: { rows: RowData[] }) => {
  // Keep a stable reference so the list doesn’t re-render unnecessarily
  const itemData = useMemo(() => rows, [rows]);

  return (
    <div className="table-container">
      {/* Sticky header */}
      <div className="table-header">
        {columns.map((col) => (
          <div key={col} className="table-cell header-cell">
            {col}
          </div>
        ))}
      </div>

      <List
        height={VISIBLE_HEIGHT}
        itemCount={rows.length}
        itemSize={ROW_HEIGHT}
        width="100%"
        itemData={itemData}
        overscanCount={8}
      >
        {VirtualRow}
      </List>
    </div>
  );
};
```

