import React, { useState, useTransition, useCallback } from 'react';

type CheckoutStep = 'cart' | 'address' | 'validating' | 'redirecting' | 'error';

interface Address {
  street: string;
  city: string;
  zip: string;
  country: string;
}

export const CheckoutFunnel = () => {
  const [step, setStep] = useState<CheckoutStep>('cart');
  const [address, setAddress] = useState<Address | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const validateAndRedirect = useCallback(async (formData: Address) => {
    setError(null);

    // Immediate UI feedback – no blocking
    startTransition(() => {
      setStep('validating');
      setAddress(formData);
    });

    try {
      // Simulate address validation (replace with real API)
      const validation = await fetch('/api/validate-address', {
        method: 'POST',
        body: JSON.stringify(formData),
      }).then(r => r.json());

      if (!validation.valid) {
        throw new Error(validation.message || 'Invalid address');
      }

      // Move to redirecting state without freezing the UI
      startTransition(() => setStep('redirecting'));

      // Payment gateway redirect (non-blocking)
      const { redirectUrl } = await fetch('/api/create-payment-session', {
        method: 'POST',
        body: JSON.stringify({ address: formData }),
      }).then(r => r.json());

      // Soft navigation / redirect
      window.location.href = redirectUrl;
    } catch (err) {
      startTransition(() => {
        setStep('error');
        setError(err instanceof Error ? err.message : 'Something went wrong');
      });
    }
  }, []);

  return (
    <div className="checkout">
      {step === 'cart' && (
        <button onClick={() => setStep('address')}>
          Proceed to Address
        </button>
      )}

      {step === 'address' && (
        <AddressForm
          onSubmit={validateAndRedirect}
          disabled={isPending}
        />
      )}

      {(step === 'validating' || step === 'redirecting') && (
        <div className="status-panel" aria-live="polite">
          <div className="spinner" />
          <p>
            {step === 'validating'
              ? 'Validating your address…'
              : 'Redirecting to secure payment…'}
          </p>
          <p className="hint">Please do not close this window.</p>
        </div>
      )}

      {step === 'error' && (
        <div className="error-panel">
          <p>{error}</p>
          <button onClick={() => setStep('address')}>
            Edit Address & Retry
          </button>
        </div>
      )}
    </div>
  );
};

// Simple controlled form (kept minimal for the snippet)
const AddressForm = ({
  onSubmit,
  disabled,
}: {
  onSubmit: (data: Address) => void;
  disabled: boolean;
}) => {
  const [form, setForm] = useState<Address>({
    street: '',
    city: '',
    zip: '',
    country: '',
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        onSubmit(form);
      }}
    >
      {/* form fields omitted for brevity – bind to form state */}
      <button type="submit" disabled={disabled}>
        {disabled ? 'Processing…' : 'Continue to Payment'}
      </button>
    </form>
  );
};

full_response:
**Recommended Solution**

The 60% drop-off is driven by a blocking UI during address validation and payment-gateway redirection. The page appears frozen because long-running async work is performed on the main thread without concurrent rendering or clear pending states.

The fix is a lightweight state machine combined with React’s concurrent features (`useTransition`) so the UI stays responsive, shows immediate feedback, and never blocks interaction.

