import React, { lazy, Suspense, useState, useTransition } from 'react';

// Only the highest-value widget is loaded immediately
const PrimaryWidget = lazy(() => import('./widgets/PrimaryWidget'));
// Everything else is deferred
const SecondaryWidgets = lazy(() => import('./widgets/SecondaryWidgets'));

type OnboardingStep = 'signup' | 'dashboard';

export const FastTTVOnboarding = () => {
  const [step, setStep] = useState<OnboardingStep>('signup');
  const [user, setUser] = useState<{ email: string } | null>(null);
  const [isPending, startTransition] = useTransition();

  // Minimal registration – only what is required to create an account
  const handleQuickSignup = async (email: string, password: string) => {
    startTransition(async () => {
      // Replace with your auth call
      const newUser = await fetch('/api/register', {
        method: 'POST',
        body: JSON.stringify({ email, password }),
      }).then(r => r.json());

      setUser(newUser);
      setStep('dashboard'); // Instant transition to value
    });
  };

  if (step === 'signup') {
    return (
      <div className="signup-minimal">
        <h1>Get started in 20 seconds</h1>
        <QuickSignupForm onSubmit={handleQuickSignup} disabled={isPending} />
        <p className="hint">You can complete your profile later.</p>
      </div>
    );
  }

  // Dashboard – PrimaryWidget appears first, rest load progressively
  return (
    <div className="dashboard">
      <header>
        <h2>Welcome{user ? `, ${user.email}` : ''}</h2>
      </header>

      <Suspense fallback={<WidgetSkeleton />}>
        <PrimaryWidget />   {/* Highest Time-to-Value surface */}
      </Suspense>

      <Suspense fallback={<WidgetSkeleton count={3} />}>
        <SecondaryWidgets /> {/* Everything else streams in */}
      </Suspense>
    </div>
  );
};

// Extremely short form – only two fields
const QuickSignupForm = ({
  onSubmit,
  disabled,
}: {
  onSubmit: (email: string, password: string) => void;
  disabled: boolean;
}) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

