    >
      <input
        type="email"
        placeholder="Work email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        required
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        required
      />
      <button type="submit" disabled={disabled}>
        {disabled ? 'Creating account…' : 'Start free trial'}
      </button>
    </form>
  );
};

const WidgetSkeleton = ({ count = 1 }: { count?: number }) => (
  <>
    {Array.from({ length: count }).map((_, i) => (
      <div key={i} className="widget-skeleton" style={{ height: 180, marginBottom: 16 }} />
    ))}
  </>
);

