import React, { lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

// Lazy load modular features to keep initial bundle size minimal
const DashboardModule = lazy(() => import('./modules/DashboardModule'));
const SettingsModule = lazy(() => import('./modules/SettingsModule'));

export const AppRouter: React.FC = () => {
  return (
    <BrowserRouter>
      <Suspense fallback={<div className="flex h-screen items-center justify-center">Loading module...</div>}>
        <Routes>
          <Route path="/dashboard" element={<DashboardModule />} />
          <Route path="/settings" element={<SettingsModule />} />
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
};

import React, { lazy, Suspense, useEffect, useState } from 'react';

// Heavy interactive widget loaded lazily on demand
const HeavyAnalyticsChart = lazy(() => import('./HeavyAnalyticsChart'));

export const MobileOptimizedDashboard: React.FC = () => {
  const [isSlowConnection, setIsSlowConnection] = useState(false);
  const [showChart, setShowChart] = useState(false);

  useEffect(() => {
    // Detect network conditions via Network Information API
    const nav = navigator as any;
    if (nav.connection) {
      const slow = nav.connection.saveData || ['slow-2g', '2g', '3g'].includes(nav.connection.effectiveType);
      setIsSlowConnection(slow);
    }
  }, []);

  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 300px), 1fr))',
      gap: '1rem',
      padding: 'clamp(1rem, 3vw, 2rem)',
      fontSize: 'clamp(0.875rem, 1vw + 0.5rem, 1.125rem)'
    }}>
      <header style={{ gridColumn: '1 / -1' }}>
        <h1 style={{ fontSize: 'clamp(1.5rem, 4vw, 2.5rem)', margin: 0 }}>
          Performance Dashboard
        </h1>
      </header>

      <section style={{ padding: '1rem', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
        <h2>Core Vitals Summary</h2>
        <p>Essential layout rendered immediately without blocking the main thread.</p>
      </section>

      <section style={{ padding: '1rem', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
        <h2>Interactive Analytics</h2>
        {isSlowConnection && !showChart ? (
          <button 
            onClick={() => setShowChart(true)}
            style={{ padding: '0.75rem 1rem', width: '100%', minHeight: '44px' }}
          >
            Load Interactive Chart (Optimized for 3G/4G)
          </button>
        ) : (
          <Suspense fallback={<div style={{ minHeight: '200px' }}>Loading chart...</div>}>
            <HeavyAnalyticsChart />
          </Suspense>
        )}
      </section>
    </div>
  );
};

full_response:
To tackle high bounce rates on 3G/4G networks and resolve mobile layout issues, we must combine **network-aware resource loading** with a **mobile-first, container-based responsive strategy**.

---

### Architectural Strategy

1. **Network-Aware Resource Loading:** High-latency mobile networks bottleneck initial render and script execution. Defer heavy UI components (e.g., interactive charts, complex dialogs, rich text editors) until the user requests them, or load lightweight fallbacks on slower connection types (`effectiveType === '3g'` or `'2g'`).
2. **Fluid Typography & Adaptive Layouts:** Avoid fixed dimensions. Use CSS `clamp()` for fluid typography and CSS Grid/Flexbox to eliminate layout shifts (CLS) on varied screen widths.
3. **Optimized Interactivity (TTI Reduction):** Yield main-thread work by utilizing non-blocking interaction hooks or dynamic imports triggered by user viewport intersection (Intersection Observer).

---

### Optimized React Implementation

The following component demonstrates **network-aware component loading** (deferring heavy widgets on slow connections) combined with a **mobile-first, fluid CSS-in-JS layout structure** to maximize TTI and responsiveness on mobile devices:

```tsx
import React, { lazy, Suspense, useEffect, useState } from 'react';

// Heavy interactive widget loaded lazily on demand
const HeavyAnalyticsChart = lazy(() => import('./HeavyAnalyticsChart'));

export const MobileOptimizedDashboard: React.FC = () => {
  const [isSlowConnection, setIsSlowConnection] = useState(false);
  const [showChart, setShowChart] = useState(false);

  useEffect(() => {
    // Detect network conditions via Network Information API
    const nav = navigator as any;
    if (nav.connection) {
      const slow = nav.connection.saveData || ['slow-2g', '2g', '3g'].includes(nav.connection.effectiveType);
      setIsSlowConnection(slow);
    }
  }, []);

  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 300px), 1fr))',
      gap: '1rem',
      padding: 'clamp(1rem, 3vw, 2rem)',
      fontSize: 'clamp(0.875rem, 1vw + 0.5rem, 1.125rem)'
    }}>
      <header style={{ gridColumn: '1 / -1' }}>
        <h1 style={{ fontSize: 'clamp(1.5rem, 4vw, 2.5rem)', margin: 0 }}>
          Performance Dashboard
        </h1>
      </header>

      <section style={{ padding: '1rem', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
        <h2>Core Vitals Summary</h2>
        <p>Essential layout rendered immediately without blocking the main thread.</p>
      </section>

      <section style={{ padding: '1rem', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
        <h2>Interactive Analytics</h2>
        {isSlowConnection && !showChart ? (
          <button 
            onClick={() => setShowChart(true)}
            style={{ padding: '0.75rem 1rem', width: '100%', minHeight: '44px' }}
          >
            Load Interactive Chart (Optimized for 3G/4G)
          </button>
        ) : (
          <Suspense fallback={<div style={{ minHeight: '200px' }}>Loading chart...</div>}>
            <HeavyAnalyticsChart />
          </Suspense>
        )}
      </section>
    </div>
  );
};

```

