import React, { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

interface AdminRow {
  id: number;
  name: string;
  email: string;
  role: string;
  status: string;
}

export const VirtualizedAdminTable: React.FC<{ data: AdminRow[] }> = ({ data }) => {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 48, // Fixed row height estimation in pixels
    overscan: 10, // Number of items to render outside the visible viewport for smooth scrolling
  });

  return (
    <div 
      ref={parentRef} 
      style={{ height: '650px', overflow: 'auto', border: '1px solid #e2e8f0', borderRadius: '8px' }}
    >
      <div
        style={{
          height: `${rowVirtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const row = data[virtualRow.index];
          return (
            <div
              key={row.id}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${virtualRow.size}px`,
                transform: `translateY(${virtualRow.start}px)`,
                display: 'grid',
                gridTemplateColumns: '80px 1fr 1fr 120px 100px',
                alignItems: 'center',
                padding: '0 1rem',
                borderBottom: '1px solid #f1f5f9',
                backgroundColor: virtualRow.index % 2 === 0 ? '#ffffff' : '#f8fafc',
                fontSize: '0.875rem'
              }}
            >
              <div>#{row.id}</div>
              <div style={{ fontWeight: 500 }}>{row.name}</div>
              <div style={{ color: '#64748b' }}>{row.email}</div>
              <div>{row.role}</div>
              <div>
                <span style={{ 
                  padding: '0.25rem 0.5rem', 
                  borderRadius: '4px', 
                  fontSize: '0.75rem',
                  backgroundColor: row.status === 'Active' ? '#dcfce7' : '#fee2e2',
                  color: row.status === 'Active' ? '#166534' : '#991b1b'
                }}>
                  {row.status}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

full_response:
### Architectural Analysis

Rendering 5,000 rows with 15 columns creates over **75,000 DOM nodes**. When the browser attempts to calculate styles, layout, and paint this massive tree all at once, the main thread locks up, causing the 4–5 second UI freeze.

For internal admin dashboards, **virtualization** is superior to traditional pagination because it allows power users to scroll, search, and scan through large datasets seamlessly without pagination friction, while keeping the active DOM footprint constrained to only what is visible on the screen.

---

### Implementation Example

The following React component uses `@tanstack/react-virtual` to virtualize the table rows. By rendering only the visible subset of rows plus a small overscan buffer, the browser workload drops drastically, eliminating the initialization freeze.

```tsx
import React, { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

interface AdminRow {
  id: number;
  name: string;
  email: string;
  role: string;
  status: string;
}

export const VirtualizedAdminTable: React.FC<{ data: AdminRow[] }> = ({ data }) => {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 48, // Fixed row height estimation in pixels
    overscan: 10, // Number of items to render outside the visible viewport for smooth scrolling
  });

  return (
    <div 
      ref={parentRef} 
      style={{ height: '650px', overflow: 'auto', border: '1px solid #e2e8f0', borderRadius: '8px' }}
    >
      <div
        style={{
          height: `${rowVirtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const row = data[virtualRow.index];
          return (
            <div
              key={row.id}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${virtualRow.size}px`,
                transform: `translateY(${virtualRow.start}px)`,
                display: 'grid',
                gridTemplateColumns: '80px 1fr 1fr 120px 100px',
                alignItems: 'center',
                padding: '0 1rem',
                borderBottom: '1px solid #f1f5f9',
                backgroundColor: virtualRow.index % 2 === 0 ? '#ffffff' : '#f8fafc',
                fontSize: '0.875rem'
              }}
            >
              <div>#{row.id}</div>
              <div style={{ fontWeight: 500 }}>{row.name}</div>
              <div style={{ color: '#64748b' }}>{row.email}</div>
              <div>{row.role}</div>
              <div>
                <span style={{ 
                  padding: '0.25rem 0.5rem', 
                  borderRadius: '4px', 
                  fontSize: '0.75rem',
                  backgroundColor: row.status === 'Active' ? '#dcfce7' : '#fee2e2',
                  color: row.status === 'Active' ? '#166534' : '#991b1b'
                }}>
                  {row.status}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

