import React, { useState, useTransition } from 'react';

type CheckoutState = 'IDLE' | 'VALIDATING_ADDRESS' | 'ADDRESS_VALID' | 'PROCESSING_PAYMENT' | 'REDIRECTING';

export const CheckoutFunnel: React.FC = () => {
  const [status, setStatus] = useState<CheckoutState>('IDLE');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const handleAddressSubmit = async (addressData: any) => {
    setStatus('VALIDATING_ADDRESS');
    setErrorMessage(null);

    try {
      // Simulate non-blocking async address validation API
      const response = await fetch('/api/validate-address', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(addressData),
      });
      const result = await response.json();

      if (!result.isValid) {
        setStatus('IDLE');
        setErrorMessage(result.message || 'Please check your address details.');
        return;
      }

      setStatus('ADDRESS_VALID');
    } catch (error) {
      setStatus('IDLE');
      setErrorMessage('Network error during validation. Please try again.');
    }
  };

  const handleProceedToPayment = () => {
    setStatus('PROCESSING_PAYMENT');

    startTransition(async () => {
      try {
        const res = await fetch('/api/create-payment-intent', { method: 'POST' });
        const { redirectUrl } = await res.json();

        setStatus('REDIRECTING');
        window.location.href = redirectUrl;
      } catch (err) {
        setStatus('ADDRESS_VALID');
        setErrorMessage('Unable to connect to payment gateway. Please retry.');
      }
    });
  };

  return (
    <div style={{ maxWidth: '600px', margin: '2rem auto', padding: '2rem', border: '1px solid #e2e8f0', borderRadius: '8px', fontFamily: 'sans-serif' }}>
      <h2>Secure Checkout</h2>

      {errorMessage && (
        <div style={{ padding: '1rem', marginBottom: '1rem', background: '#fee2e2', color: '#991b1b', borderRadius: '4px', fontSize: '0.875rem' }}>
          {errorMessage}
        </div>
      )}

      {status === 'IDLE' && (
        <form onSubmit={(e) => { e.preventDefault(); handleAddressSubmit({ address: '123 Main St' }); }}>
          <p style={{ color: '#475569', fontSize: '0.875rem' }}>Enter your shipping address to continue:</p>
          <input type="text" placeholder="Shipping Address" defaultValue="123 Main St" style={{ width: '100%', padding: '0.75rem', marginBottom: '1rem', borderRadius: '4px', border: '1px solid #cbd5e1' }} />
          <button type="submit" style={{ width: '100%', padding: '0.75rem', background: '#0284c7', color: '#fff', border: 'none', borderRadius: '4px', fontWeight: 600, cursor: 'pointer' }}>
            Validate Address
          </button>
        </form>
      )}

      {status === 'VALIDATING_ADDRESS' && (
        <div style={{ textAlign: 'center', padding: '2rem', color: '#0284c7' }}>
          <p>Verifying address details...</p>
        </div>
      )}

      {status === 'ADDRESS_VALID' && (
        <div>
          <p style={{ color: '#166534', fontWeight: 500, marginBottom: '1rem' }}>✓ Address verified successfully.</p>
          <button 
            onClick={handleProceedToPayment} 
            disabled={isPending}
            style={{ width: '100%', padding: '0.75rem', background: '#16a34a', color: '#fff', border: 'none', borderRadius: '4px', fontWeight: 600, cursor: 'pointer' }}
          >
            Proceed to Payment
          </button>
        </div>
      )}

      {(status === 'PROCESSING_PAYMENT' || status === 'REDIRECTING') && (
        <div style={{ textAlign: 'center', padding: '2rem', background: '#f8fafc', borderRadius: '8px' }}>
          <div style={{ fontSize: '1rem', fontWeight: 600, color: '#1e293b', marginBottom: '0.5rem' }}>
            {status === 'PROCESSING_PAYMENT' ? 'Securing your transaction...' : 'Redirecting to payment gateway...'}
          </div>
          <p style={{ color: '#64748b', fontSize: '0.875rem', margin: 0 }}>Please do not close this window or click back.</p>
        </div>
      )}
    </div>
  );
};

