```

**Also required (config, not code):**
- `index.html`: `<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">`, plus `<link rel="preconnect">` for your API and CDN origins.
- `vite.config.ts`: `build.target = "es2020"` and `manualChunks: { react: ["react", "react-dom", "react-router-dom"] }` for a long-cached vendor chunk.
- Fonts: subsetted WOFF2 with `font-display: swap`.

## Expected impact and caveats

- Splitting code and deferring below-the-fold work typically cuts initial JS by 40-60%. Your actual gain depends on what's in the bundle today.
- Explicit image dimensions and reserved section heights fix most CLS.
- Prerendering gives the largest drop in perceived load time on 3G, but it needs real architectural work.
- If the page scrolls sideways, find the offending element (a fixed `width`, a wide table, an unwrapped `pre`) instead of hiding it with `overflow-x: hidden`.
- Validate each change against RUM segmented by connection type. If bounce doesn't improve, check for non-performance causes such as a confusing first screen, aggressive popups, or a slow API, using session recordings.

If you share a throttled mobile Lighthouse report and your top three entry pages, I can tell you which of these changes will matter most.

code:
// VirtualizedTable.tsx
import { memo, useDeferredValue, useMemo, useRef, useState } from "react";
import { QueryClient, QueryClientProvider, useQuery } from "@tanstack/react-query";
import { useVirtualizer } from "@tanstack/react-virtual";

/* ---------- Types and column definitions (15 columns in the real app) ---------- */
type DataRow = { id: string; [key: string]: string | number };
type Column = { key: string; label: string; width: number };

const COLUMNS: Column[] = [
  { key: "id", label: "ID", width: 100 },
  { key: "name", label: "Name", width: 200 },
  { key: "email", label: "Email", width: 240 },
  { key: "status", label: "Status", width: 120 },
  { key: "amount", label: "Amount", width: 120 },
  // ...add the remaining columns here
];

const ROW_HEIGHT = 40; // fixed height keeps scroll math cheap and accurate
const GRID_TEMPLATE = COLUMNS.map((c) => `${c.width}px`).join(" ");
const TOTAL_WIDTH = COLUMNS.reduce((sum, c) => sum + c.width, 0);

/* ---------- Memoized row: skips re-render unless its own props change ---------- */
const TableRow = memo(function TableRow({
  row,
  start,
}: {
  row: DataRow;
  start: number;
}) {
  return (
    <div
      role="row"
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: TOTAL_WIDTH,
        height: ROW_HEIGHT,
        transform: `translateY(${start}px)`,
        display: "grid",
        gridTemplateColumns: GRID_TEMPLATE,
        alignItems: "center",
        borderBottom: "1px solid #eee",
      }}
    >
      {COLUMNS.map((c) => (
        <div
          role="cell"
          key={c.key}
          style={{ padding: "0 12px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}
        >
          {row[c.key]}
        </div>
      ))}
    </div>
  );
});

/* ---------- Table ---------- */
function DataTable() {
  const { data = [], isLoading, error } = useQuery<DataRow[]>({
    queryKey: ["admin-rows"],
    queryFn: async () => {
      const res = await fetch("/api/rows");
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
    staleTime: 60_000, // reuse cached data when navigating back to this page
  });

  const [filter, setFilter] = useState("");
  const deferredFilter = useDeferredValue(filter); // typing never waits on filtering
  const [sort, setSort] = useState<{ key: string; dir: 1 | -1 } | null>(null);

  // Filter and sort once per change, not on every render or scroll
  const rows = useMemo(() => {
    const q = deferredFilter.trim().toLowerCase();
    let out = q
      ? data.filter((r) => COLUMNS.some((c) => String(r[c.key]).toLowerCase().includes(q)))
      : data;
    if (sort) {
      const { key, dir } = sort;
      out = [...out].sort((a, b) => {
        const x = a[key], y = b[key];
        if (typeof x === "number" && typeof y === "number") return (x - y) * dir;
        return String(x).localeCompare(String(y)) * dir;
      });
    }
    return out;
  }, [data, deferredFilter, sort]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => ROW_HEIGHT,
    overscan: 10, // a few extra rows avoid blank flashes during fast scrolling
  });

  const toggleSort = (key: string) =>
    setSort((s) => (s?.key === key ? (s.dir === 1 ? { key, dir: -1 } : null) : { key, dir: 1 }));

  if (isLoading) return <p aria-busy="true">Loading data…</p>;
  if (error) return <p role="alert">Failed to load data.</p>;

  return (
    <section>
      <input
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
        placeholder="Filter rows"
        aria-label="Filter rows"
        style={{ marginBottom: 8, minHeight: 36 }}
      />
      <span style={{ marginLeft: 12 }}>{rows.length.toLocaleString()} rows</span>

      {/* One scroll container for both axes keeps the header aligned with the body */}
      <div
        ref={scrollRef}
        role="table"
        aria-rowcount={rows.length}
        style={{ height: "70vh", overflow: "auto", border: "1px solid #ddd" }}
      >
        <div
          role="row"
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1,
            width: TOTAL_WIDTH,
            display: "grid",
            gridTemplateColumns: GRID_TEMPLATE,
            background: "#f7f7f7",
            borderBottom: "2px solid #ccc",
            fontWeight: 600,
          }}
        >
          {COLUMNS.map((c) => (
            <button
              key={c.key}
              role="columnheader"
              onClick={() => toggleSort(c.key)}
              style={{ all: "unset", cursor: "pointer", padding: "10px 12px" }}
            >
              {c.label}
              {sort?.key === c.key ? (sort.dir === 1 ? " ▲" : " ▼") : ""}
            </button>
          ))}
        </div>

        {/* Total height keeps the scrollbar accurate; only visible rows are mounted */}
        <div style={{ position: "relative", width: TOTAL_WIDTH, height: virtualizer.getTotalSize() }}>
          {virtualizer.getVirtualItems().map((v) => (
            <TableRow key={rows[v.index].id} row={rows[v.index]} start={v.start} />
          ))}
        </div>
      </div>
    </section>
  );
}

const queryClient = new QueryClient();

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <DataTable />
    </QueryClientProvider>
  );
}

