// VirtualizedTable.jsx — handles 5,000+ rows without freezing
import { FixedSizeList as List } from "react-window";

export default function VirtualizedTable({ rows }) {
  const Row = ({ index, style }) => {
    const row = rows[index];
    return (
      <div style={{ ...style, display: "flex", borderBottom: "1px solid #eee" }}>
        {Object.values(row).map((cell, i) => (
          <div key={i} style={{ flex: 1, padding: "4px 8px" }}>
            {cell}
          </div>
        ))}
      </div>
    );
  };

  return (
    <List
      height={600}        // viewport height
      itemCount={rows.length}
      itemSize={40}       // row height
      width={"100%"}
    >
      {Row}
    </List>
  );
}

full_response:
The freeze happens because React is trying to render **75,000 DOM cells** (5,000 rows × 15 columns). This matches known performance bottlenecks where oversized DOM trees cause multi‑second UI stalls   [bytechalk.com](https://www.bytechalk.com/blog/react-large-table-performance-optimization)  [dev-resource.com](https://dev-resource.com/performance-optimization-for-react-data-tables-large-datasets/).  
The fastest fix is **virtualization**, which keeps only ~20–40 visible rows in the DOM instead of thousands. This reduces render time from hundreds of milliseconds to ~1–3 ms even for very large datasets   [mbloging.com](https://www.mbloging.com/post/optimize-large-json-data-rendering-react).

Below is a **single React code snippet** using `react-window` to virtualize your table.

---

```tsx
// VirtualizedTable.jsx — handles 5,000+ rows without freezing
import { FixedSizeList as List } from "react-window";

export default function VirtualizedTable({ rows }) {
  const Row = ({ index, style }) => {
    const row = rows[index];
    return (
      <div style={{ ...style, display: "flex", borderBottom: "1px solid #eee" }}>
        {Object.values(row).map((cell, i) => (
          <div key={i} style={{ flex: 1, padding: "4px 8px" }}>
            {cell}
          </div>
        ))}
      </div>
    );
  };

  return (
    <List
      height={600}        // viewport height
      itemCount={rows.length}
      itemSize={40}       // row height
      width={"100%"}
    >
      {Row}
    </List>
  );
}
```

---

### Why this fixes the freeze
- **Virtualization renders only visible rows**, keeping the DOM under ~40 nodes instead of 75,000.  
- This eliminates layout thrashing and reduces initial render time from seconds to milliseconds (validated in multiple benchmarks)   [dev-resource.com](https://dev-resource.com/performance-optimization-for-react-data-tables-large-datasets/).
- Scrolling stays smooth because off‑screen rows are never mounted.

---

### If you prefer pagination instead
Pagination reduces the dataset to ~50–100 rows per page, which also avoids DOM overload.  
However, virtualization provides the **best UX** for admin dashboards where users expect continuous scrolling.

